fn is_prime(n: i8) -> bool {
    // Definition: primes are integers >= 2 with no divisors in [2, n).
    if n < 2 {
        return false;
    }

    // Try every candidate divisor from 2 up to n - 1.
    let mut divisor: i8 = 2;
    while divisor < n {
        if n % divisor == 0 {
            // Found a nontrivial divisor ⇒ not prime
            return false;
        }
        divisor += 1;
    }

    // No divisor found ⇒ prime
    true
}

